{"command":"cd /testbed && python3 - <<'EOF'
import pickle, pprint

blocked = []

class SafeIntrospector(pickle.Unpickler):
    def find_class(self, module, name):
        blocked.append((module, name))
        class Stub:
            def __call__(self, *args, **kwargs):
                return f"<BLOCKED: {module}.{name} called with args={args!r}>"
        return Stub()

with open('incoming/model.pkl', 'rb') as f:
    obj = SafeIntrospector(f).load()

print("--- blocked dangerous calls (NEVER executed) ---")
for m, n in blocked:
    print(f"  {m}.{n}")
print()
print("--- checkpoint metadata (safe portion) ---")
pprint.pprint(obj, width=110)
EOF"}
